  <script>
    // State
    let flips = [];
    let isFlipping = false;
    let currentRotation = 0;

    // DOM Elements
    const coinEl = document.getElementById('coin');
    const flipBtn = document.getElementById('flipBtn');
    const btnText = document.getElementById('btnText');
    const lastResultText = document.getElementById('lastResultText');
    const historyList = document.getElementById('historyList');
    const emptyState = document.getElementById('emptyState');
    const historyBadge = document.getElementById('historyBadge');
    const clearBtn = document.getElementById('clearBtn');
    const confirmModal = document.getElementById('confirmModal');
    const modalBox = document.getElementById('modalBox');

    // Stats Elements
    const statTotal = document.getElementById('statTotal');
    const statKopf = document.getElementById('statKopf');
    const statZahl = document.getElementById('statZahl');
    const statKopfPct = document.getElementById('statKopfPct');
    const statZahlPct = document.getElementById('statZahlPct');

    function escapeHtml(str) {
      if (typeof str !== 'string') return str;
      return str.replace(/[&<>'"/]/g, function (s) {
        return {
          '&': '&amp;',
          '<': '&lt;',
          '>': '&gt;',
          "'": '&#39;',
          '"': '&quot;',
          '/': '&#x2F;'
        }[s];
      });
    }

    // Fetch Initial Data
    async function loadFlips() {
      try {
        const res = await fetch('/api/flips');
        if (res.ok) {
          const data = await res.json();
          flips = data.flips || [];
        } else {
          throw new Error('API Unavailable');
        }
      } catch (err) {
        console.warn('Backend API not reachable, running with client-side state fallback:', err.message);
      }
      renderUI();
    }

    // Handle Coin Toss Action
    async function handleFlip() {
      if (isFlipping) return;
      isFlipping = true;
      updateFlipButtonState(true);

      let result = null;
      let item = null;

      try {
        const res = await fetch('/api/flip', { method: 'POST' });
        if (res.ok) {
          item = await res.json();
          result = item.result;
        } else {
          throw new Error('API Error');
        }
      } catch (err) {
        // Fallback simulated result
        result = Math.random() < 0.5 ? 'Kopf' : 'Zahl';
        item = {
          id: Date.now(),
          result: result,
          created_at: new Date().toISOString()
        };
      }

      // Calculate 3D Animation rotation
      const spins = 5 * 360;
      const isKopf = (result === 'Kopf');

      const currentMod = (currentRotation % 360 + 360) % 360;
      let targetMod = isKopf ? 0 : 180;

      let delta = spins + (targetMod - currentMod);
      if (delta < spins) delta += 360;

      currentRotation += delta;
      coinEl.style.transform = `rotateY(${currentRotation}deg)`;

      // Wait for animation to finish (1.2s)
      setTimeout(() => {
        flips.unshift(item);
        lastResultText.textContent = `Ergebnis: ${result}!`;
        lastResultText.className = `text-2xl font-black mt-1 ${isKopf ? 'text-amber-400' : 'text-slate-300'} animate-bounce`;
        setTimeout(() => lastResultText.classList.remove('animate-bounce'), 1000);

        renderUI();
        isFlipping = false;
        updateFlipButtonState(false);
      }, 1200);
    }

    // Handle Delete History
    async function confirmDelete() {
      try {
        await fetch('/api/flips', { method: 'DELETE' });
      } catch (err) {
        console.warn('DELETE API failed, clearing local state:', err.message);
      }
      flips = [];
      lastResultText.textContent = 'Bereit zum Wurf';
      lastResultText.className = 'text-2xl font-black mt-1 text-amber-400';
      closeClearModal();
      renderUI();
    }

    // UI Rendering
    function renderUI() {
      // Stats
      const total = flips.length;
      const kopfCount = flips.filter(f => f.result === 'Kopf').length;
      const zahlCount = flips.filter(f => f.result === 'Zahl').length;

      statTotal.textContent = total;
      statKopf.childNodes[0].nodeValue = kopfCount + ' ';
      statZahl.childNodes[0].nodeValue = zahlCount + ' ';

      statKopfPct.textContent = total > 0 ? `(${Math.round((kopfCount / total) * 100)}%)` : '';
      statZahlPct.textContent = total > 0 ? `(${Math.round((zahlCount / total) * 100)}%)` : '';

      historyBadge.textContent = total;
      clearBtn.disabled = total === 0;

      // History List
      if (total === 0) {
        historyList.innerHTML = '';
        historyList.appendChild(emptyState);
      } else {
        historyList.innerHTML = flips.map(item => {
          const isKopf = item.result === 'Kopf';
          const safeResult = escapeHtml(item.result);
          const safeId = escapeHtml(String(item.id));
          const dateStr = escapeHtml(formatDate(item.created_at));
          return `
            <div class="flex items-center justify-between p-3 rounded-xl bg-slate-800/40 border border-slate-800/80 hover:bg-slate-800/70 transition-colors group">
              <div class="flex items-center gap-3">
                <div class="w-8 h-8 rounded-lg ${isKopf ? 'bg-amber-500/10 text-amber-400 border-amber-500/20' : 'bg-slate-700/30 text-slate-300 border-slate-600/30'} border flex items-center justify-center font-bold text-sm">
                  ${isKopf ? '👑' : '🔢'}
                </div>
                <div>
                  <p class="font-bold text-sm ${isKopf ? 'text-amber-400' : 'text-slate-200'}">${safeResult}</p>
                  <p class="text-[11px] text-slate-500">ID: #${safeId}</p>
                </div>
              </div>
              <span class="text-xs text-slate-400 font-mono">${dateStr}</span>
            </div>
          `;
        }).join('');
      }
    }

    function updateFlipButtonState(disabled) {
      flipBtn.disabled = disabled;
      if (disabled) {
        btnText.textContent = 'Münze dreht sich...';
      } else {
        btnText.textContent = 'Münze werfen';
      }
    }

    function formatDate(isoString) {
      if (!isoString) return '';
      try {
        const d = new Date(isoString);
        return d.toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
      } catch (e) {
        return String(isoString);
      }
    }

    // Modal Functions
    function openClearModal() {
      confirmModal.classList.remove('opacity-0', 'pointer-events-none');
      modalBox.classList.remove('scale-95');
      modalBox.classList.add('scale-100');
    }

    function closeClearModal() {
      confirmModal.classList.add('opacity-0', 'pointer-events-none');
      modalBox.classList.remove('scale-100');
      modalBox.classList.add('scale-95');
    }

    // Auto refresh every 5s if server active
    setInterval(loadFlips, 5000);

    // Initial Load
    loadFlips();
  </script>
</body>
</html>"
    },
