      "path": "main.py",
      "content": "import logging
import os
import secrets
from datetime import datetime, timezone
from contextlib import asynccontextmanager
from typing import List, Generator

from fastapi import FastAPI, Depends, HTTPException, status
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import FileResponse
from pydantic import BaseModel, Field
from sqlalchemy import create_engine, Column, Integer, String, DateTime
from sqlalchemy.orm import declarative_base, sessionmaker, Session

# Configure structured logging
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(name)s - %(levelname)s - %(message)s"
)
logger = logging.getLogger("muenzwurf_app")

# Database Setup
DATABASE_URL = os.getenv("DATABASE_URL", "sqlite:///./flips.db")

engine = create_engine(
    DATABASE_URL,
    connect_args={"check_same_thread": False} if DATABASE_URL.startswith("sqlite") else {}
)
SessionLocal = sessionmaker(autocommit=False, autoflush=False, bind=engine)
Base = declarative_base()


class FlipModel(Base):
    __tablename__ = "flips"

    id = Column(Integer, primary_key=True, index=True)
    result = Column(String(10), nullable=False)
    created_at = Column(DateTime(timezone=True), nullable=False)


@asynccontextmanager
async def lifespan(app: FastAPI):
    # Startup: Ensure DB tables are created
    logger.info("Initializing database tables...")
    Base.metadata.create_all(bind=engine)
    logger.info("Database initialized successfully.")
    yield
    # Shutdown
    logger.info("Shutting down application...")


app = FastAPI(
    title="Münzwurf API",
    description="Backend API für Münzwurf App mit Verlaufshistorie",
    version="1.0.0",
    lifespan=lifespan
)

# CORS Configuration
ALLOWED_ORIGINS = os.getenv("ALLOWED_ORIGINS", "http://localhost:8000,http://127.0.0.1:8000").split(",")
app.add_middleware(
    CORSMiddleware,
    allow_origins=ALLOWED_ORIGINS,
    allow_credentials=True,
    allow_methods=["GET", "POST", "DELETE", "OPTIONS"],
    allow_headers=["*"],
)


# Pydantic Models adhering strictly to specification
class FlipResponse(BaseModel):
    id: int = Field(..., description="Eindeutige ID des Münzwurfs")
    result: str = Field(..., description="Ergebnis des Münzwurfs (Kopf | Zahl)")
    created_at: str = Field(..., description="Zeitstempel im ISO 8601 Format")

    model_config = {
        "json_schema_extra": {
            "example": {
                "id": 1,
                "result": "Kopf",
                "created_at": "2023-10-27T10:00:00Z"
            }
        }
    }


class FlipsListResponse(BaseModel):
    flips: List[FlipResponse] = Field(..., description="Liste aller Münzwürfe chronologisch absteigend")


class MessageResponse(BaseModel):
    message: str = Field(..., description="Bestätigungsmeldung")


# Database session dependency
def get_db() -> Generator[Session, None, None]:
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()


def _format_iso(dt: datetime) -> str:
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt.isoformat()


@app.get("/", include_in_schema=False)
async def serve_index():
    """Serves the index.html file if present."""
    if os.path.exists("index.html"):
        return FileResponse("index.html")
    raise HTTPException(
        status_code=status.HTTP_404_NOT_FOUND,
        detail="index.html file not found on server."
    )


@app.post(
    "/api/flip",
    response_model=FlipResponse,
    status_code=status.HTTP_201_CREATED,
    summary="Führt einen Münzwurf aus",
    description="Führt einen Münzwurf serverseitig aus und speichert das Ergebnis in der Datenbank."
)
async def create_flip(db: Session = Depends(get_db)):
    try:
        outcome = secrets.choice(["Kopf", "Zahl"])
        now = datetime.now(timezone.utc)

        db_flip = FlipModel(
            result=outcome,
            created_at=now
        )
        db.add(db_flip)
        db.commit()
        db.refresh(db_flip)

        logger.info(f"Neuer Münzwurf erstellt: ID={db_flip.id}, Ergebnis={db_flip.result}")

        return FlipResponse(
            id=db_flip.id,
            result=db_flip.result,
            created_at=_format_iso(db_flip.created_at)
        )
    except Exception as e:
        db.rollback()
        logger.error(f"Fehler beim Ausführen des Münzwurfs: {str(e)}", exc_info=True)
        raise HTTPException(
            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
            detail="Münzwurf konnte nicht gespeichert werden."
        )


@app.get(
    "/api/flips",
    response_model=FlipsListResponse,
    summary="Ruft den Verlauf der Münzwürfe ab",
    description="Ruft alle bisherigen Münzwürfe chronologisch absteigend ab."
)
async def get_flips(db: Session = Depends(get_db)):
    try:
        flips = db.query(FlipModel).order_by(FlipModel.created_at.desc(), FlipModel.id.desc()).all()
        flip_responses = [
            FlipResponse(
                id=flip.id,
                result=flip.result,
                created_at=_format_iso(flip.created_at)
            )
            for flip in flips
        ]
        return FlipsListResponse(flips=flip_responses)
    except Exception as e:
        logger.error(f"Fehler beim Abrufen der Münzwürfe: {str(e)}", exc_info=True)
        raise HTTPException(
            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
            detail="Verlauf konnte nicht abgerufen werden."
        )


@app.delete(
    "/api/flips",
    response_model=MessageResponse,
    summary="Löscht den gesamten Verlauf",
    description="Löscht den gesamten Verlauf der Münzwürfe aus der Datenbank."
)
async def delete_flips(db: Session = Depends(get_db)):
    try:
        num_deleted = db.query(FlipModel).delete()
        db.commit()
        logger.info(f"{num_deleted} Münzwürfe aus der Datenbank gelöscht.")
        return MessageResponse(message="Verlauf erfolgreich gelöscht.")
    except Exception as e:
        db.rollback()
        logger.error(f"Fehler beim Löschen des Verlaufs: {str(e)}", exc_info=True)
        raise HTTPException(
            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
            detail="Verlauf konnte nicht gelöscht werden."
        )
