    const errorMessage = document.getElementById('error-message');

    // Format Currency Safely
    function formatCurrency(amount) {
      const val = Number.isFinite(amount) ? amount : 0;
      return new Intl.NumberFormat('de-DE', { style: 'currency', currency: 'EUR' }).format(val);
    }

    function showError(msg) {
      errorMessage.textContent = msg;
      errorBanner.classList.remove('hidden');
    }

    function hideError() {
      errorBanner.classList.add('hidden');
    }

    // Set Selected Tip Percentage
    function setPercentage(val, isCustom = false) {
      selectedPercentage = Math.max(0, parseFloat(val) || 0);

      tipBtns.forEach(btn => {
        const btnVal = parseFloat(btn.dataset.tip);
        if (!isCustom && btnVal === selectedPercentage) {
          btn.classList.add('bg-emerald-600', 'text-white', 'shadow-md');
          btn.classList.remove('bg-slate-100', 'text-slate-700');
        } else {
          btn.classList.remove('bg-emerald-600', 'text-white', 'shadow-md');
          btn.classList.add('bg-slate-100', 'text-slate-700');
        }
      });

      if (!isCustom) {
        customTipInput.value = '';
      }

      triggerCalculation();
    }

    // Render Output Results Safely using textContent (XSS Prevention)
    function renderResults(tipAmount, totalAmount) {
      tipPercentDisplay.textContent = `(${selectedPercentage}%)`;
      tipAmountDisplay.textContent = formatCurrency(tipAmount);
      totalAmountDisplay.textContent = formatCurrency(totalAmount);

      const perPerson = splitCount > 0 ? totalAmount / splitCount : totalAmount;
      perPersonDisplay.textContent = formatCurrency(perPerson);

      if (splitCount > 1) {
        splitRow.classList.remove('opacity-60');
      } else {
        splitRow.classList.add('opacity-60');
      }
    }

    // Calculation Logic with Backend API call + Client Fallback
    async function calculate() {
      hideError();
      const rawBillValue = billInput.value.trim();

      if (rawBillValue === '') {
        renderResults(0, 0);
        return;
      }

      const billAmount = parseFloat(rawBillValue);

      if (isNaN(billAmount) || billAmount <= 0) {
        showError('Bitte geben Sie einen positiven Rechnungsbetrag ein.');
        renderResults(0, 0);
        return;
      }

      if (billAmount > 100000000) {
        showError('Rechnungsbetrag überschreitet das zulässige Limit.');
        renderResults(0, 0);
        return;
      }

      try {
        const response = await fetch('/api/calculate', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            bill_amount: billAmount,
            tip_percentage: selectedPercentage
          })
        });

        if (response.ok) {
          const data = await response.json();
          renderResults(data.tip_amount, data.total_amount);
          return;
        } else if (response.status === 422) {
          showError('Ungültige Parameter an den Server übergeben.');
          renderResults(0, 0);
          return;
        }
      } catch (err) {
        // Fallback for offline/preview mode
      }

      // Fallback Local Calculation
      const tipAmount = Math.round(billAmount * (selectedPercentage / 100) * 100) / 100;
      const totalAmount = Math.round((billAmount + tipAmount) * 100) / 100;
      renderResults(tipAmount, totalAmount);
    }

    // Debounced Calculation Trigger
    function triggerCalculation() {
      clearTimeout(debounceTimer);
      debounceTimer = setTimeout(calculate, 150);
    }

    // Event Listeners
    billInput.addEventListener('input', triggerCalculation);

    tipBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        setPercentage(parseFloat(btn.dataset.tip));
      });
    });

    customTipInput.addEventListener('input', (e) => {
      setPercentage(e.target.value, true);
    });

    btnDecrement.addEventListener('click', () => {
      if (splitCount > 1) {
        splitCount--;
        splitLabel.textContent = `${splitCount} ${splitCount === 1 ? 'Person' : 'Personen'}`;
        triggerCalculation();
      }
    });

    btnIncrement.addEventListener('click', () => {
      if (splitCount < 100) {
        splitCount++;
        splitLabel.textContent = `${splitCount} Personen`;
        triggerCalculation();
      }
    });

