import os
from fastapi import FastAPI, HTTPException, Request, status
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import FileResponse, JSONResponse
from pydantic import BaseModel, Field

# Configure structured logging
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(name)s: %(message)s"
)
logger = logging.getLogger("trinkgeld_rechner")

app = FastAPI(
    title="Trinkgeld-Rechner API",
    description="API zur Berechnung von Trinkgeldern und Gesamtsummen.",
    version="1.0.0"
)

# DoS Protection: Restrict body size (Max 10 KB)
MAX_PAYLOAD_SIZE_BYTES = 10240


@app.middleware("http")
async def limit_payload_size(request: Request, call_next):
    content_length = request.headers.get("content-length")
    if content_length and int(content_length) > MAX_PAYLOAD_SIZE_BYTES:
        return JSONResponse(
            status_code=status.HTTP_413_PAYLOAD_TOO_LARGE,
            content={"detail": "Payload zu groß. Maximal 10 KB erlaubt."}
        )
    return await call_next(request)


# Configure CORS handling securely
allowed_origins_env = os.getenv("ALLOWED_ORIGINS", "http://localhost:8000,http://127.0.0.1:8000")
allowed_origins = [origin.strip() for origin in allowed_origins_env.split(",") if origin.strip()]

app.add_middleware(
    CORSMiddleware,
    allow_origins=allowed_origins,
    allow_credentials=False,
    allow_methods=["GET", "POST", "OPTIONS"],
    allow_headers=["Content-Type", "Authorization"],
)


class CalculateRequest(BaseModel):
    bill_amount: float = Field(
        ...,
        gt=0,
        le=100_000_000.0,
        description="Der Rechnungsbetrag (muss größer als 0 und maximal 100M sein)",
        examples=[45.50]
    )
    tip_percentage: float = Field(
        ...,
        ge=0,
        le=1000.0,
        description="Der Trinkgeld-Prozentsatz (muss >= 0 und maximal 1000% sein)",
        examples=[15.0]
    )


class CalculateResponse(BaseModel):
    bill_amount: float = Field(..., description="Ursprünglicher Rechnungsbetrag")
    tip_percentage: float = Field(..., description="Gewählter Trinkgeld-Prozentsatz")
    tip_amount: float = Field(..., description="Berechneter Trinkgeldbetrag")
    total_amount: float = Field(..., description="Gesamtsumme inkl. Trinkgeld")


@app.get("/", include_in_schema=False)
async def serve_root():
    """Serves static index.html if present, else health status JSON."""
    if os.path.exists("index.html"):
        return FileResponse("index.html")
    return JSONResponse(
        status_code=status.HTTP_200_OK,
        content={"message": "Trinkgeld-Rechner API online", "docs": "/docs"}
    )


@app.post(
    "/api/calculate",
    response_model=CalculateResponse,
    status_code=status.HTTP_200_OK,
    summary="Berechnet den Trinkgeldbetrag und die Gesamtsumme",
    description="Berechnet den Trinkgeldbetrag und die Gesamtsumme basierend auf dem Rechnungsbetrag und dem Prozentwert."
)
async def calculate_tip(request: CalculateRequest):
    try:
        logger.info(
            f"Calculation requested: bill_amount={request.bill_amount}, tip_percentage={request.tip_percentage}"
        )
        tip_amount = round(request.bill_amount * (request.tip_percentage / 100.0), 2)
        total_amount = round(request.bill_amount + tip_amount, 2)

        return CalculateResponse(
            bill_amount=round(request.bill_amount, 2),
            tip_percentage=round(request.tip_percentage, 2),
            tip_amount=tip_amount,
            total_amount=total_amount
        )
    except Exception as e:
        logger.error(f"Unhandled calculation error: {str(e)}")
        raise HTTPException(
            status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
            detail="Interner Serverfehler bei der Berechnung."
        )
