  <script>
    // Fallback list of words matching standard backend schema in case standard endpoint is offline
    const MOCK_WORDS = [
      "Sonnenschein", 
      "Abenteuer", 
      "Kaffeesatz", 
      "Zukunftsmusik", 
      "Wolkenkratzer"
    ];

    let currentWord = "";
    let historyList = [];
    let favoritesList = JSON.parse(localStorage.getItem('zufallswort_favs') || '[]');
    let activeTab = 'history';
    let audioEnabled = true;
    let isFetching = false;

    // Audio Synthesizer for feedback clicks
    const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    function playTone(freq, type = 'sine', duration = 0.08) {
      if (!audioEnabled || !audioCtx) return;
      try {
        if (audioCtx.state === 'suspended') audioCtx.resume();
        const osc = audioCtx.createOscillator();
        const gain = audioCtx.createGain();
        osc.type = type;
        osc.frequency.setValueAtTime(freq, audioCtx.currentTime);
        gain.gain.setValueAtTime(0.08, audioCtx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + duration);
        osc.connect(gain);
        gain.connect(audioCtx.destination);
        osc.start();
        osc.stop(audioCtx.currentTime + duration);
      } catch (e) {}
    }

    function toggleAudio() {
      audioEnabled = !audioEnabled;
      const icon = document.getElementById('sound-icon');
      if (audioEnabled) {
        icon.className = 'fa-solid fa-volume-high';
        showToast('Ton aktiviert');
      } else {
        icon.className = 'fa-solid fa-volume-xmark text-slate-500';
        showToast('Ton stummgeschaltet');
      }
    }

    // Main API Fetch Function
    async function fetchWord() {
      if (isFetching) return;
      isFetching = true;

      const btn = document.getElementById('generate-btn');
      const btnIcon = document.getElementById('btn-icon');
      const btnSpinner = document.getElementById('btn-spinner');
      const btnText = document.getElementById('btn-text');
      const wordDisplay = document.getElementById('word-display');
      const wordActions = document.getElementById('word-actions');
      const wordLengthTag = document.getElementById('word-length-tag');

      // UI Loading state
      btn.disabled = true;
      btnIcon.classList.add('hidden');
      btnSpinner.classList.remove('hidden');
      btnText.innerText = 'Lade Wort...';
      playTone(440, 'sine', 0.05);

      let fetchedWord = "";

      try {
        // Consume backend endpoint /api/word
        const response = await fetch('/api/word', { 
          method: 'GET',
          headers: { 'Accept': 'application/json' }
        });

        if (response.ok) {
          const data = await response.json();
          fetchedWord = data.word;
        } else {
          throw new Error('Fallback response');
        }
      } catch (err) {
        // Fallback for environment preview if /api/word route is offline
        const randomIndex = Math.floor(Math.random() * MOCK_WORDS.length);
        fetchedWord = MOCK_WORDS[randomIndex];
      }

      setTimeout(() => {
        currentWord = fetchedWord;

        // Animate Word Display
        wordDisplay.classList.remove('animate-pop-in');
        void wordDisplay.offsetWidth;
        wordDisplay.innerText = currentWord;
        wordDisplay.classList.add('animate-pop-in');

        // Word Length Tag
        wordLengthTag.innerText = `${currentWord.length} Zeichen`;
        wordLengthTag.classList.remove('hidden');

        // Enable Quick Action Toolbar
        wordActions.classList.remove('opacity-40', 'pointer-events-none');
        updateFavoriteButtonState();

        // Add to History
        addToHistory(currentWord);

        // Restore Button State
        btn.disabled = false;
        btnIcon.classList.remove('hidden');
        btnSpinner.classList.add('hidden');
        btnText.innerText = 'Wort zeigen';
        isFetching = false;

        playTone(660, 'triangle', 0.12);
      }, 200);
    }

    // History Management
    function addToHistory(word) {
      if (historyList[0] === word) return;
      historyList.unshift(word);
      if (historyList.length > 20) historyList.pop();
      renderHistory();
    }

    function renderHistory() {
      const container = document.getElementById('tab-history-content');
      const countEl = document.getElementById('history-count');

      countEl.innerText = historyList.length;
      if (historyList.length === 0) {
        container.innerHTML = '<p id="history-empty" class="text-xs text-slate-500 italic py-3 w-full text-center">Noch keine Wörter generiert.</p>';
        return;
      }

      container.innerHTML = historyList.map(w => `
        <button onclick="selectSavedWord('${escapeHtml(w)}')" class="px-2.5 py-1 rounded-lg bg-slate-800/80 hover:bg-slate-700/90 text-slate-300 hover:text-white text-xs transition-all border border-slate-700/40 flex items-center gap-1.5 active:scale-95 group">
          <span>${escapeHtml(w)}</span>
        </button>
      `).join('');
    }

    // Favorites Management
    function toggleFavorite() {
      if (!currentWord) return;
      const index = favoritesList.indexOf(currentWord);
      if (index > -1) {
        favoritesList.splice(index, 1);
        showToast('Aus Favoriten entfernt');
      } else {
        favoritesList.push(currentWord);
        showToast('Zu Favoriten hinzugefügt', 'fa-star text-amber-400');
      }
      localStorage.setItem('zufallswort_favs', JSON.stringify(favoritesList));
      updateFavoriteButtonState();
      renderFavorites();
    }

    function updateFavoriteButtonState() {
      const favIcon = document.getElementById('fav-icon');
      const isFav = favoritesList.includes(currentWord);
      if (isFav) {
        favIcon.className = 'fa-solid fa-star text-amber-400';
      } else {
        favIcon.className = 'fa-regular fa-star text-amber-400';
      }
    }

    function renderFavorites() {
      const container = document.getElementById('tab-favs-content');
      const countEl = document.getElementById('favs-count');

      countEl.innerText = favoritesList.length;
      if (favoritesList.length === 0) {
        container.innerHTML = '<p id="favs-empty" class="text-xs text-slate-500 italic py-3 w-full text-center">Keine Favoriten gespeichert.</p>';
        return;
      }

      container.innerHTML = favoritesList.map(w => `
        <button onclick="selectSavedWord('${escapeHtml(w)}')" class="px-2.5 py-1 rounded-lg bg-amber-950/30 hover:bg-amber-900/40 text-amber-200 text-xs transition-all border border-amber-800/40 flex items-center gap-1.5 active:scale-95">
          <i class="fa-solid fa-star text-[10px] text-amber-400"></i>
          <span>${escapeHtml(w)}</span>
        </button>
      `).join('');
    }

    function selectSavedWord(word) {
      currentWord = word;
      const wordDisplay = document.getElementById('word-display');
      const wordActions = document.getElementById('word-actions');
      const wordLengthTag = document.getElementById('word-length-tag');

      wordDisplay.classList.remove('animate-pop-in');
      void wordDisplay.offsetWidth;
      wordDisplay.innerText = word;
      wordDisplay.classList.add('animate-pop-in');

      wordLengthTag.innerText = `${word.length} Zeichen`;
      wordLengthTag.classList.remove('hidden');
      wordActions.classList.remove('opacity-40', 'pointer-events-none');
      updateFavoriteButtonState();
      playTone(520, 'sine', 0.08);
    }

    function clearCurrentTab() {
      if (activeTab === 'history') {
        historyList = [];
        renderHistory();
        showToast('Verlauf geleert');
      } else {
        favoritesList = [];
        localStorage.removeItem('zufallswort_favs');
        renderFavorites();
        updateFavoriteButtonState();
        showToast('Favoriten geleert');
      }
    }

    function switchTab(tab) {
      activeTab = tab;
      const histBtn = document.getElementById('tab-history-btn');
      const favsBtn = document.getElementById('tab-favs-btn');
      const histContent = document.getElementById('tab-history-content');
      const favsContent = document.getElementById('tab-favs-content');

      if (tab === 'history') {
        histBtn.className = 'text-cyan-400 border-b-2 border-cyan-400 pb-1 font-semibold transition-all flex items-center gap-1.5';
        favsBtn.className = 'text-slate-400 hover:text-slate-200 pb-1 transition-all flex items-center gap-1.5';
        histContent.classList.remove('hidden');
        favsContent.classList.add('hidden');
      } else {
        favsBtn.className = 'text-amber-400 border-b-2 border-amber-400 pb-1 font-semibold transition-all flex items-center gap-1.5';
        histBtn.className = 'text-slate-400 hover:text-slate-200 pb-1 transition-all flex items-center gap-1.5';
        favsContent.classList.remove('hidden');
        histContent.classList.add('hidden');
      }
    }

    // Copy word to Clipboard
    async function copyWord() {
      if (!currentWord) return;
      try {
        await navigator.clipboard.writeText(currentWord);
        showToast('In die Zwischenablage kopiert!', 'fa-copy text-cyan-400');
        playTone(800, 'sine', 0.06);
      } catch (e) {
        showToast('Kopieren fehlgeschlagen');
      }
    }

    // Speech synthesis
    function speakWord() {
      if (!currentWord) return;
      if ('speechSynthesis' in window) {
        window.speechSynthesis.cancel();
        const utterance = new SpeechSynthesisUtterance(currentWord);
        utterance.lang = 'de-DE';
        utterance.rate = 0.9;
        window.speechSynthesis.speak(utterance);
        playTone(500, 'triangle', 0.05);
      } else {
        showToast('Sprachausgabe nicht unterstützt');
      }
    }

    // UI Toast Notification Helper
    let toastTimeout;
    function showToast(message, iconClass = 'fa-circle-check text-cyan-400') {
      const toast = document.getElementById('toast');
      const toastMsg = document.getElementById('toast-msg');
      const toastIcon = document.getElementById('toast-icon');

      toastMsg.innerText = message;
      toastIcon.className = `fa-solid ${iconClass}`;

      toast.classList.remove('opacity-0', 'translate-y-3', 'pointer-events-none');
      toast.classList.add('opacity-100', 'translate-y-0');

      clearTimeout(toastTimeout);
      toastTimeout = setTimeout(() => {
        toast.classList.remove('opacity-100', 'translate-y-0');
        toast.classList.add('opacity-0', 'translate-y-3', 'pointer-events-none');
      }, 2200);
    }

    // Shortcuts Modal Toggle
    function toggleShortcutsModal() {
      const modal = document.getElementById('shortcuts-modal');
      if (modal.classList.contains('opacity-0')) {
        modal.classList.remove('opacity-0', 'pointer-events-none');
      } else {
        modal.classList.add('opacity-0', 'pointer-events-none');
      }
    }

    function escapeHtml(str) {
      return str.replace(/[&<>'""]/g, function(m) {
        return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' }[m];
      });
    }

    // Global Keyboard Shortcuts
    document.addEventListener('keydown', (e) => {
      if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') return;

      if (e.code === 'Space' || e.code === 'Enter') {
        e.preventDefault();
        fetchWord();
      } else if (e.code === 'KeyC' && currentWord) {
        copyWord();
      } else if (e.code === 'KeyV' && currentWord) {
        speakWord();
      } else if (e.code === 'Escape') {
        const modal = document.getElementById('shortcuts-modal');
        if (!modal.classList.contains('opacity-0')) {
          toggleShortcutsModal();
        }
      }
    });

    // Initialize Favorites on Load
    renderFavorites();
  </script>
</body>
</html>"
