      "content": "import os
import random
import logging
from fastapi import FastAPI
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import FileResponse, HTMLResponse
from pydantic import BaseModel, Field

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(name)s - %(levelname)s - %(message)s"
)
logger = logging.getLogger("zufallswort-app")

# Fest hinterlegte Liste von 5 Wörtern laut Spezifikation
WORD_LIST = [
    "Sonnenschein",
    "Abenteuer",
    "Kaffeesatz",
    "Zukunftsmusik",
    "Wolkenkratzer"
]

app = FastAPI(
    title="Mini-App Zufallswort Generator",
    description="API zur Generierung zufälliger Wörter aus einer vordefinierten Liste.",
    version="1.0.0"
)

# Restrictive CORS configuration for security
allowed_origins_raw = os.getenv("ALLOWED_ORIGINS", "http://localhost:8000,http://127.0.0.1:8000")
allowed_origins = [origin.strip() for origin in allowed_origins_raw.split(",") if origin.strip()]

app.add_middleware(
    CORSMiddleware,
    allow_origins=allowed_origins,
    allow_credentials=False,
    allow_methods=["GET", "OPTIONS"],
    allow_headers=["*"],
)


class WordResponse(BaseModel):
    word: str = Field(..., description="Das zufällig ausgewählte Wort", examples=["Sonnenschein"])


@app.get(
    "/api/word",
    response_model=WordResponse,
    summary="Zufallswort abrufen",
    description="Liefert zufällig ein Wort aus einer fest hinterlegten Liste von 5 Wörtern zurück."
)
async def get_random_word():
    selected_word = random.choice(WORD_LIST)
    logger.info(f"Zufallswort abgefragt: {selected_word}")
    return WordResponse(word=selected_word)


@app.get("/", response_class=HTMLResponse, include_in_schema=False)
async def serve_ui():
    if os.path.exists("index.html"):
        return FileResponse("index.html")
    return HTMLResponse("<!DOCTYPE html><html><body><h1>Zufallswort Generator API</h1><p>Besuche /api/word</p></body></html>")
