import os
import secrets
from fastapi import FastAPI, Request, status
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import FileResponse, JSONResponse
from pydantic import BaseModel, Field

# Configure structured logging
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(name)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger("dice_roller")

app = FastAPI(
    title="Mini Dice Roller API",
    description="Generates random dice rolls and serves a modern web interface.",
    version="1.0.0",
)

# CORS configuration
raw_origins = os.getenv("ALLOWED_ORIGINS", "http://localhost:8000,http://127.0.0.1:8000")
allowed_origins = [origin.strip() for origin in raw_origins.split(",") if origin.strip()]

app.add_middleware(
    CORSMiddleware,
    allow_origins=allowed_origins,
    allow_credentials=False,
    allow_methods=["GET", "OPTIONS"],
    allow_headers=["Content-Type", "Accept"],
)


class DiceRollResponse(BaseModel):
    result: int = Field(
        ...,
        ge=1,
        le=6,
        description="Random integer result between 1 and 6 inclusive",
        json_schema_extra={"example": 4},
    )


@app.exception_handler(Exception)
async def global_exception_handler(request: Request, exc: Exception):
    logger.error(f"Unhandled error on {request.url.path}: {exc}", exc_info=True)
    return JSONResponse(
        status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
        content={"detail": "An internal server error occurred. Please try again later."},
    )


@app.get(
    "/api/roll",
    response_model=DiceRollResponse,
    summary="Roll a 6-sided die",
    description="Generates and returns a random integer between 1 and 6 inclusive.",
    status_code=status.HTTP_200_OK,
)
async def roll_dice() -> DiceRollResponse:
    """Generates and returns a random integer between 1 and 6 inclusive using CSPRNG."""
    roll = secrets.randbelow(6) + 1
    logger.info(f"Dice roll generated: {roll}")
    return DiceRollResponse(result=roll)


@app.get("/", response_class=FileResponse, include_in_schema=False)
async def serve_ui():
    """Serves the single-page HTML/JS/CSS frontend for the Mini Dice Roller."""
    index_path = os.path.join(os.path.dirname(__file__), "index.html")
    if os.path.exists(index_path):
        return FileResponse(index_path, media_type="text/html")
    return JSONResponse(
        status_code=status.HTTP_404_NOT_FOUND,
        content={"detail": "index.html not found"},
    )
