from pydantic import BaseModel, Field

app = FastAPI(
    title="Random Color Generator API",
    description="Backend API for generating random color palettes with live health monitoring badge.",
    version="1.0.0"
)

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=False,
    allow_methods=["GET", "POST", "OPTIONS"],
    allow_headers=["*"],
)

class HealthResponse(BaseModel):
    status: str = Field(..., description="Returns operational health status")

class ColorDetail(BaseModel):
    hex: str = Field(..., description="Hexadecimal color code with leading #")
    rgb: str = Field(..., description="RGB color representation")
    hsl: str = Field(..., description="HSL color representation")
    is_dark: bool = Field(..., description="True if background color is dark")
    contrast_text: str = Field(..., description="Recommended text color for high contrast (#000000 or #FFFFFF)")

class PaletteResponse(BaseModel):
    colors: List[ColorDetail]
    harmony: str

def rgb_to_hex(r: int, g: int, b: int) -> str:
    return f"#{r:02X}{g:02X}{b:02X}"

def rgb_to_hsl(r: int, g: int, b: int) -> tuple[int, int, int]:
    r_norm, g_norm, b_norm = r / 255.0, g / 255.0, b / 255.0
    cmax = max(r_norm, g_norm, b_norm)
    cmin = min(r_norm, g_norm, b_norm)
    delta = cmax - cmin

    if delta == 0:
        h = 0
    elif cmax == r_norm:
        h = 60 * (((g_norm - b_norm) / delta) % 6)
    elif cmax == g_norm:
        h = 60 * (((b_norm - r_norm) / delta) + 2)
    else:
        h = 60 * (((r_norm - g_norm) / delta) + 4)

    l = (cmax + cmin) / 2
    s = 0 if delta == 0 else delta / (1 - abs(2 * l - 1))

    return int(round(h)) % 360, int(round(s * 100)), int(round(l * 100))

def hsl_to_rgb(h: int, s: int, l: int) -> tuple[int, int, int]:
    h_deg = h % 360
    s_norm = s / 100.0
    l_norm = l / 100.0

    c = (1 - abs(2 * l_norm - 1)) * s_norm
    x = c * (1 - abs((h_deg / 60) % 2 - 1))
    m = l_norm - c / 2

    if 0 <= h_deg < 60:
        r_p, g_p, b_p = c, x, 0
    elif 60 <= h_deg < 120:
        r_p, g_p, b_p = x, c, 0
    elif 120 <= h_deg < 180:
        r_p, g_p, b_p = 0, c, x
    elif 180 <= h_deg < 240:
        r_p, g_p, b_p = 0, x, c
    elif 240 <= h_deg < 300:
        r_p, g_p, b_p = x, 0, c
    else:
        r_p, g_p, b_p = c, 0, x

    r = int(round((r_p + m) * 255))
    g = int(round((g_p + m) * 255))
    b = int(round((b_p + m) * 255))

    return max(0, min(255, r)), max(0, min(255, g)), max(0, min(255, b))

def get_contrast_color(r: int, g: int, b: int) -> tuple[bool, str]:
    def adjust(val):
        v = val / 255.0
        return v / 12.92 if v <= 0.03928 else ((v + 0.055) / 1.055) ** 2.4

    luminance = 0.2126 * adjust(r) + 0.7152 * adjust(g) + 0.0722 * adjust(b)
    is_dark = luminance < 0.5
    contrast_text = "#FFFFFF" if is_dark else "#000000"
    return is_dark, contrast_text

def build_color_detail(r: int, g: int, b: int) -> ColorDetail:
    h, s, l = rgb_to_hsl(r, g, b)
    is_dark, contrast_text = get_contrast_color(r, g, b)
    return ColorDetail(
        hex=rgb_to_hex(r, g, b),
        rgb=f"rgb({r}, {g}, {b})",
        hsl=f"hsl({h}, {s}%, {l}%)",
        is_dark=is_dark,
        contrast_text=contrast_text
    )

def generate_harmony_palette(count: int = 5, mode: str = "random") -> List[ColorDetail]:
    base_h = random.randint(0, 359)
    base_s = random.randint(45, 90)
    base_l = random.randint(35, 65)

    colors = []
    if mode == "monochromatic":
        for i in range(count):
            l = max(10, min(90, base_l + (i - count // 2) * 15))
            r, g, b = hsl_to_rgb(base_h, base_s, l)
            colors.append(build_color_detail(r, g, b))
    elif mode == "analogous":
        for i in range(count):
            h = (base_h + (i - count // 2) * 30) % 360
            r, g, b = hsl_to_rgb(h, base_s, base_l)
            colors.append(build_color_detail(r, g, b))
    elif mode == "complementary":
        for i in range(count):
            h = base_h if i % 2 == 0 else (base_h + 180) % 360
            l = max(15, min(85, base_l + ((i // 2) - 1) * 20))
            r, g, b = hsl_to_rgb(h, base_s, l)
            colors.append(build_color_detail(r, g, b))
    elif mode == "triadic":
        for i in range(count):
            offset = (i % 3) * 120
            h = (base_h + offset) % 360
            l = max(20, min(80, base_l + (i // 3) * 15))
            r, g, b = hsl_to_rgb(h, base_s, l)
            colors.append(build_color_detail(r, g, b))
    else:
        for _ in range(count):
            r = random.randint(0, 255)
            g = random.randint(0, 255)
            b = random.randint(0, 255)
            colors.append(build_color_detail(r, g, b))

    return colors

@app.get("/health", response_model=HealthResponse, tags=["Health"])
async def get_health():
    """Returns backend operational status for health monitoring."""
    return HealthResponse(status="healthy")

@app.get("/api/colors/random", response_model=ColorDetail, tags=["Colors"])
async def get_random_color():
    """Generates a single random color with HEX, RGB, HSL, and contrast details."""
    r = random.randint(0, 255)
    g = random.randint(0, 255)
    b = random.randint(0, 255)
    return build_color_detail(r, g, b)

@app.get("/api/palette/random", response_model=PaletteResponse, tags=["Colors"])
async def get_random_palette(
    count: int = Query(default=5, ge=1, le=10, description="Number of colors in palette (1-10)"),
    harmony: str = Query(default="random", description="Color harmony mode: random, monochromatic, analogous, complementary, triadic")
):
    """Generates a color palette based on specified count and color harmony type."""
    mode = harmony.lower() if harmony.lower() in ["random", "monochromatic", "analogous", "complementary", "triadic"] else "random"
    palette = generate_harmony_palette(count=count, mode=mode)
    return PaletteResponse(colors=palette, harmony=mode)

