from fastapi import FastAPI, status
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import HTMLResponse
from pydantic import BaseModel
from dotenv import load_dotenv

load_dotenv()

app = FastAPI(
    title="Random Number Generator API",
    description="Service for checking system health and generating random numbers (1-100).",
    version="1.0.0"
)

# Configure CORS strictly avoiding wildcard '*'
allowed_origins_raw = os.getenv("ALLOWED_ORIGINS", "http://localhost:8000,http://127.0.0.1:8000,http://localhost:3000")
allowed_origins = [origin.strip() for origin in allowed_origins_raw.split(",") if origin.strip()]

app.add_middleware(
    CORSMiddleware,
    allow_origins=allowed_origins,
    allow_credentials=True,
    allow_methods=["GET"],
    allow_headers=["*"],
)


class HealthResponse(BaseModel):
    status: str


class RandomNumberResponse(BaseModel):
    number: int


@app.get("/health", response_model=HealthResponse, status_code=status.HTTP_200_OK)
async def get_health():
    """Returns current system health status."""
    return HealthResponse(status="ok")


@app.get("/api/random", response_model=RandomNumberResponse, status_code=status.HTTP_200_OK)
async def get_random_number():
    """Generates and returns a random integer between 1 and 100 inclusive."""
    random_val = random.randint(1, 100)
    return RandomNumberResponse(number=random_val)


