        <div class="flex-1">
          <h3 id="notificationTitle" class="text-sm font-semibold"></h3>
          <p id="notificationMessage" class="text-sm mt-0.5 opacity-90"></p>
          <p id="notificationId" class="text-xs font-mono mt-1 opacity-75 hidden"></p>
        </div>
        <button onclick="dismissNotification()" class="text-slate-400 hover:text-slate-600 p-1 rounded-lg hover:bg-black/5">
          <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/>
          </svg>
        </button>
      </div>
    </div>

    <div class="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">

      <!-- Form Section -->
      <div class="lg:col-span-5 bg-white rounded-2xl border border-slate-200/80 shadow-sm p-6 sm:p-8 space-y-6">
        <div>
          <h2 class="text-xl font-bold text-slate-900">Kontakt aufnehmen</h2>
          <p class="text-sm text-slate-500 mt-1">Tragen Sie Ihre Daten ein, um eine Anfrage per API zu übermitteln.</p>
        </div>

        <form id="contactForm" onsubmit="handleSubmit(event)" class="space-y-5" novalidate>

          <!-- InputField (Name) -->
          <div>
            <label for="nameInput" class="block text-xs font-semibold uppercase tracking-wider text-slate-700 mb-1.5">
              Name <span class="text-rose-500">*</span>
            </label>
            <div class="relative">
              <input 
                type="text" 
                id="nameInput" 
                name="name" 
                placeholder="z. B. Max Mustermann"
                maxLength="100"
                oninput="validateField('name')"
                class="w-full px-3.5 py-2.5 rounded-xl border border-slate-300 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-600 transition-colors placeholder:text-slate-400"
              />
            </div>
            <p id="nameError" class="text-xs text-rose-500 mt-1 hidden"></p>
          </div>

          <!-- InputField (Email) -->
          <div>
            <label for="emailInput" class="block text-xs font-semibold uppercase tracking-wider text-slate-700 mb-1.5">
              E-Mail Adresse <span class="text-rose-500">*</span>
            </label>
            <div class="relative">
              <input 
                type="email" 
                id="emailInput" 
                name="email" 
                placeholder="max@beispiel.de"
                maxLength="255"
                oninput="validateField('email')"
                class="w-full px-3.5 py-2.5 rounded-xl border border-slate-300 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-600 transition-colors placeholder:text-slate-400"
              />
            </div>
            <p id="emailError" class="text-xs text-rose-500 mt-1 hidden"></p>
          </div>

          <!-- SubmitButton -->
          <button 
            type="submit" 
            id="submitBtn"
            class="w-full py-3 px-4 bg-indigo-600 hover:bg-indigo-700 active:bg-indigo-800 text-white font-medium text-sm rounded-xl shadow-md shadow-indigo-100 transition-all focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:ring-offset-2 flex items-center justify-center gap-2 cursor-pointer disabled:opacity-60 disabled:cursor-not-allowed"
          >
            <span id="submitBtnText">Absenden</span>
            <svg id="submitSpinner" class="w-4 h-4 animate-spin hidden" fill="none" viewBox="0 0 24 24">
              <circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"></circle>
              <path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
            </svg>
