        <div class="relative">
          <input 
            type="text" 
            id="searchInput" 
            oninput="renderContacts()" 
            placeholder="Kontakte durchsuchen..."
            class="w-full pl-9 pr-4 py-2 bg-slate-50 rounded-xl border border-slate-200 text-xs focus:outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500"
          />
          <svg class="w-4 h-4 text-slate-400 absolute left-3 top-2.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/>
          </svg>
        </div>

        <!-- List -->
        <div id="contactsList" class="space-y-3 max-h-[420px] overflow-y-auto pr-1">
