  </main>

  <!-- Footer -->
  <footer class="bg-white border-t border-slate-200 py-4 mt-auto">
    <div class="max-w-5xl mx-auto px-4 text-center text-xs text-slate-400">
      Kontakt Mini-App &bull; Tailwind CSS + Vanilla JS &bull; REST API `/api/contact`
    </div>
  </footer>

  <!-- Script Logic -->
  <script>
    // Local Data Store
    let mockDatabase = [];

    // Form Validation Helpers
    function validateField(field) {
      if (field === 'name') {
        const val = document.getElementById('nameInput').value.trim();
        const errorEl = document.getElementById('nameError');
        if (!val) {
          errorEl.textContent = 'Name darf nicht leer sein.';
          errorEl.classList.remove('hidden');
          return false;
        } else if (val.length > 100) {
          errorEl.textContent = 'Name darf maximal 100 Zeichen lang sein.';
          errorEl.classList.remove('hidden');
          return false;
        } else {
          errorEl.classList.add('hidden');
          return true;
        }
      }

      if (field === 'email') {
        const val = document.getElementById('emailInput').value.trim();
        const errorEl = document.getElementById('emailError');
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!val) {
          errorEl.textContent = 'E-Mail ist erforderlich.';
          errorEl.classList.remove('hidden');
          return false;
        } else if (!emailRegex.test(val)) {
          errorEl.textContent = 'Bitte eine gültige E-Mail-Adresse eingeben.';
          errorEl.classList.remove('hidden');
          return false;
        } else if (val.length > 255) {
          errorEl.textContent = 'E-Mail darf maximal 255 Zeichen lang sein.';
          errorEl.classList.remove('hidden');
          return false;
        } else {
          errorEl.classList.add('hidden');
          return true;
        }
      }
      return true;
    }

    // Notification Banner Handling
    let bannerTimeout = null;
    function showNotification(type, title, message, id = '') {
      const banner = document.getElementById('notificationBanner');
      const card = document.getElementById('notificationCard');
      const icon = document.getElementById('notificationIcon');
      const titleEl = document.getElementById('notificationTitle');
      const messageEl = document.getElementById('notificationMessage');
      const idEl = document.getElementById('notificationId');

      if (type === 'success') {
        card.className = "p-4 rounded-xl border flex items-start gap-3 shadow-sm bg-emerald-50 border-emerald-200 text-emerald-900";
        icon.innerHTML = `<svg class="w-5 h-5 text-emerald-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>`;
      } else {
        card.className = "p-4 rounded-xl border flex items-start gap-3 shadow-sm bg-rose-50 border-rose-200 text-rose-900";
        icon.innerHTML = `<svg class="w-5 h-5 text-rose-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>`;
      }

      titleEl.textContent = title;
      messageEl.textContent = message;

      if (id) {
        idEl.textContent = `ID: ${id}`;
        idEl.classList.remove('hidden');
      } else {
        idEl.classList.add('hidden');
      }

      banner.classList.remove('hidden');

      if (bannerTimeout) clearTimeout(bannerTimeout);
      bannerTimeout = setTimeout(() => {
        dismissNotification();
      }, 6000);
    }

    function dismissNotification() {
      const banner = document.getElementById('notificationBanner');
      banner.classList.add('hidden');
    }

    // Submit Form
    async function handleSubmit(event) {
      event.preventDefault();

      const isNameValid = validateField('name');
      const isEmailValid = validateField('email');

      if (!isNameValid || !isEmailValid) {
        showNotification('error', 'Eingabefehler', 'Bitte korrigieren Sie die markierten Felder im Formular.');
        return;
      }

      const submitBtn = document.getElementById('submitBtn');
      const submitBtnText = document.getElementById('submitBtnText');
      const submitSpinner = document.getElementById('submitSpinner');
      const nameVal = document.getElementById('nameInput').value;
      const emailVal = document.getElementById('emailInput').value;

      // UI Loading State
      submitBtn.disabled = true;
      submitBtnText.textContent = 'Wird gesendet...';
      submitSpinner.classList.remove('hidden');

      try {
        const response = await fetch('/api/contact', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({
            name: nameVal,
            email: emailVal
          })
        });

        const data = await response.json();

        if (response.ok && (data.success !== false)) {
          showNotification('success', 'Erfolgreich gesendet', data.message || 'Kontakt erfolgreich gespeichert.', data.id || '');
          document.getElementById('contactForm').reset();
          fetchContacts();
        } else {
          const detailMsg = Array.isArray(data.detail) ? data.detail.map(e => e.msg).join(', ') : data.message;
          showNotification('error', 'Fehler beim Speichern', detailMsg || 'Die Anfrage konnte nicht verarbeitet werden.');
        }
      } catch (error) {
        showNotification('error', 'Netzwerkfehler', 'Verbindung zum API-Endpunkt fehlgeschlagen.');
      } finally {
        submitBtn.disabled = false;
        submitBtnText.textContent = 'Absenden';
        submitSpinner.classList.add('hidden');
      }
    }

    // Delete Contact locally
    function deleteContact(id) {
      mockDatabase = mockDatabase.filter(c => String(c.id) !== String(id));
      renderContacts();
    }

    // Render Contacts List
    function renderContacts() {
      const container = document.getElementById('contactsList');
      const countBadge = document.getElementById('contactCount');
      const query = (document.getElementById('searchInput').value || '').toLowerCase();

      const filtered = mockDatabase.filter(c => 
        (c.name || '').toLowerCase().includes(query) || (c.email || '').toLowerCase().includes(query)
      );

      countBadge.textContent = `${mockDatabase.length} ${mockDatabase.length === 1 ? 'Eintrag' : 'Einträge'}`;

      if (filtered.length === 0) {
        container.innerHTML = `
          <div class="text-center py-8 px-4 border border-dashed border-slate-200 rounded-xl">
            <svg class="w-8 h-8 text-slate-300 mx-auto mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M20 13V6a2 2 0 00-2-2H6a2 2 0 00-2 2v7m16 0v5a2 2 0 01-2 2H6a2 2 0 01-2-2v-5m16 0h-2.586a1 1 0 00-.707.293l-2.414 2.414a1 1 0 01-.707.293h-3.172a1 1 0 01-.707-.293l-2.414-2.414A1 1 0 006.586 13H4"/>
            </svg>
            <p class="text-xs text-slate-500">Keine Kontakte gefunden.</p>
          </div>
        `;
        return;
      }

      container.innerHTML = filtered.map(item => `
        <div class="p-3.5 bg-slate-50 rounded-xl border border-slate-200/80 hover:border-slate-300 transition-all flex items-center justify-between gap-3 group">
          <div class="flex items-center gap-3 min-w-0">
            <div class="w-9 h-9 rounded-full bg-indigo-100 text-indigo-700 font-bold flex items-center justify-center shrink-0 text-xs uppercase">
              ${escapeHtml((item.name || '??').substring(0, 2))}
            </div>
            <div class="min-w-0">
              <div class="flex items-center gap-2">
                <h4 class="text-sm font-semibold text-slate-800 truncate">${escapeHtml(item.name || '')}</h4>
                ${item.id ? `<span class="text-[10px] font-mono text-slate-400 bg-white px-1.5 py-0.5 rounded border border-slate-200 shrink-0">${escapeHtml(String(item.id))}</span>` : ''}
              </div>
              <p class="text-xs text-slate-500 truncate mt-0.5">${escapeHtml(item.email || '')}</p>
            </div>
          </div>
          <div class="flex items-center gap-1 opacity-80 group-hover:opacity-100 transition-opacity shrink-0">
            <button 
              onclick="deleteContact('${escapeHtml(String(item.id))}')" 
              title="Löschen"
              class="p-1.5 text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition-colors"
            >
              <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/>
              </svg>
            </button>
          </div>
        </div>
      `).join('');
    }

    function escapeHtml(str) {
      if (typeof str !== 'string') str = String(str || '');
      return str.replace(/[&<>'" ]/g, 
        tag => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[tag] || tag)
      );
    }

    async function fetchContacts() {
      try {
        const res = await fetch('/api/contact');
        if (res.ok) {
          const data = await res.json();
          if (Array.isArray(data)) {
            mockDatabase = data;
          } else if (data && Array.isArray(data.contacts)) {
            mockDatabase = data.contacts;
          }
          renderContacts();
        }
      } catch (err) {
        renderContacts();
      }
    }

    // Initial Render
    document.addEventListener('DOMContentLoaded', () => {
      fetchContacts();
    });
  </script>
</body>
</html>"
    },
    {
      "path": "main.py",
      "content": "import os
from typing import List, Optional
from fastapi import FastAPI, status
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import FileResponse
from pydantic import BaseModel, EmailStr, Field

app = FastAPI(title="Contact API")

raw_origins = os.getenv("ALLOWED_ORIGINS", "http://localhost:8000,http://127.0.0.1:8000")
allowed_origins = [origin.strip() for origin in raw_origins.split(",") if origin.strip()]

app.add_middleware(
    CORSMiddleware,
    allow_origins=allowed_origins,
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

contacts_db: List[dict] = []
id_counter: int = 1


class ContactCreate(BaseModel):
    name: str = Field(..., min_length=1, max_length=100)
    email: EmailStr = Field(..., max_length=255)
    message: Optional[str] = Field(default="", max_length=1000)


@app.get("/")
async def serve_index():
    index_path = "index.html"
    if not os.path.exists(index_path):
        with open(index_path, "w", encoding="utf-8") as f:
            f.write("<!DOCTYPE html><html><head><title>Contact</title></head><body><h1>Contact Service</h1></body></html>")
    return FileResponse(index_path)


@app.get("/api/contact")
async def get_contacts():
    return contacts_db


@app.post("/api/contact", status_code=status.HTTP_200_OK)
async def create_contact(contact: ContactCreate):
    global id_counter
    new_id = id_counter
    id_counter += 1

    record = {
        "id": str(new_id),
        "name": contact.name,
        "email": contact.email,
        "message": contact.message
    }
    contacts_db.append(record)

    return {
        "success": True,
        "message": f"Danke, {contact.name}!",
        "id": str(new_id)
    }
